IF OBJECT_ID('dbo.SalesOrder', 'U') IS NOT NULL DROP TABLE dbo.SalesOrder;
IF OBJECT_ID('dbo.CustomerData', 'U') IS NOT NULL DROP TABLE dbo.CustomerData;
IF OBJECT_ID('dbo.Sales', 'U') IS NOT NULL DROP TABLE dbo.Sales;
IF OBJECT_ID('dbo.Date', 'U') IS NOT NULL DROP TABLE dbo.Date;
IF OBJECT_ID('dbo.ProductData', 'U') IS NOT NULL DROP TABLE dbo.ProductData;
IF OBJECT_ID('dbo.SalesTerritory', 'U') IS NOT NULL DROP TABLE dbo.SalesTerritory;
IF OBJECT_ID('dbo.Reseller', 'U') IS NOT NULL DROP TABLE dbo.Reseller;



IF OBJECT_ID('dbo.IndividualCustomer', 'U') IS NOT NULL DROP TABLE dbo.IndividualCustomer;
IF OBJECT_ID('dbo.Customer', 'U') IS NOT NULL DROP TABLE dbo.Customer;
IF OBJECT_ID('dbo.ProductDimCategory', 'U') IS NOT NULL DROP TABLE dbo.ProductDimCategory;
IF OBJECT_ID('dbo.Item', 'U') IS NOT NULL DROP TABLE dbo.Item;
IF OBJECT_ID('dbo.Product', 'U') IS NOT NULL DROP TABLE dbo.Product;
IF OBJECT_ID('dbo.TransactionLineItem', 'U') IS NOT NULL DROP TABLE dbo.TransactionLineItem;
IF OBJECT_ID('dbo.Transaction', 'U') IS NOT NULL DROP TABLE dbo.[Transaction];
IF OBJECT_ID('dbo.Channel', 'U') IS NOT NULL DROP TABLE dbo.Channel;
IF OBJECT_ID('dbo.ChannelType', 'U') IS NOT NULL DROP TABLE dbo.ChannelType;
IF OBJECT_ID('dbo.Territory', 'U') IS NOT NULL DROP TABLE dbo.Territory;
IF OBJECT_ID('dbo.Location', 'U') IS NOT NULL DROP TABLE dbo.Location;
IF OBJECT_ID('dbo.Country', 'U') IS NOT NULL DROP TABLE dbo.Country; 





CREATE TABLE SalesOrder (
    SalesOrderLine NVARCHAR(100),
    SalesOrder NVARCHAR(100),
    SalesOrderLineKey INT,
    Channel NVARCHAR(100)
);

CREATE TABLE CustomerData (
    CustomerKey INT,
    CustomerId NVARCHAR(100),
    Customer NVARCHAR(100),
    City NVARCHAR(100),
    StateProvince NVARCHAR(100),
    CountryRegion NVARCHAR(100),
    PostalCode NVARCHAR(100)
);

CREATE TABLE Sales (
    SalesAmount DECIMAL(18,2),
    TotalProductCost DECIMAL(18,2),
    ProductStandardCost DECIMAL(18,2),
    UnitPriceDiscountPct DECIMAL(5,2),
    ExtendedAmount DECIMAL(18,2),
    UnitPrice DECIMAL(18,2),
    OrderQuantity INT,
    SalesTerritoryKey INT,
    ShipDateKey INT,
    DueDateKey INT,
    OrderDateKey INT,
    ProductKey INT,
    CustomerKey INT,
    ResellerKey INT,
    SalesOrderLineKey INT
);

CREATE TABLE Date (
    DateKey INT,
    Date NVARCHAR(100),
    FiscalYear NVARCHAR(20),
    FiscalQuarter NVARCHAR(20),
    Month NVARCHAR(50),
    FullDate NVARCHAR(100),
    MonthKey NVARCHAR(50)
);

CREATE TABLE ProductData (
    Category NVARCHAR(100),
    Subcategory NVARCHAR(100),
    Model NVARCHAR(100),
    ListPrice DECIMAL(18,2),
    Color NVARCHAR(50),
    StandardCost DECIMAL(18,2),
    Product NVARCHAR(100),
    SKU NVARCHAR(100),
    ProductKey INT
);

CREATE TABLE SalesTerritory (
    SalesTerritoryKey INT,
    Region NVARCHAR(100),
    Country NVARCHAR(100),
    [Group] NVARCHAR(100)
);

CREATE TABLE Reseller (
    PostalCode NVARCHAR(50),
    CountryRegion NVARCHAR(100),
    StateProvince NVARCHAR(100),
    City NVARCHAR(100),
    Reseller NVARCHAR(100),
    BusinessType NVARCHAR(100),
    ResellerId NVARCHAR(100),
    ResellerKey INT
);





CREATE TABLE IndividualCustomer (
    CustomerId INT,
    IndividualCustomerName NVARCHAR(100)
);

CREATE TABLE Customer (
    CustomerId INT,
    CustomerKey NVARCHAR(100),
    LocationId INT
);

CREATE TABLE ProductDimCategory (
    ProductId INT,
    Model NVARCHAR(100),
    Category NVARCHAR(100),
    Subcategory NVARCHAR(100)
);

CREATE TABLE Item (
    ItemSku NVARCHAR(100),
    StandardCost DECIMAL(18,2),
    ListPrice DECIMAL(18,2)
);

CREATE TABLE Product (
    ProductId INT,
    ProductName NVARCHAR(100),
    ItemSku NVARCHAR(100),
    ProductColor NVARCHAR(100)
);

CREATE TABLE TransactionLineItem (
    TransactionId NVARCHAR(100),
    TransactionLineItemId INT,
    ProductId INT,
    Quantity DECIMAL(18,2),
    ProductListPriceAmount DECIMAL(18,2),
    TransactionProductPriceAmount DECIMAL(18,2),
    TotalTransactionLineItemAmount DECIMAL(18,2),
    TotalTransactionSalesPriceAmount DECIMAL(18,2),
    ProductPriceAdjustmentPercentage NVARCHAR(50),
    OrderDateKey INT,
    DueDateKey INT,
    ShipDateKey INT
);

CREATE TABLE [Transaction] (
    TransactionId NVARCHAR(100),
    CustomerId INT,
    ChannelId INT
);

CREATE TABLE Channel (
    ChannelId INT,
    ChannelName NVARCHAR(100),
    ChannelTypeId INT,
    TerritoryId INT,
    ChannelKey NVARCHAR(100)
);

CREATE TABLE ChannelType (
    ChannelTypeId INT,
    ChannelTypeName NVARCHAR(100)
);

CREATE TABLE Territory (
    TerritoryId INT,
    [Group] NVARCHAR(100),
    Country NVARCHAR(100),
    Region NVARCHAR(100)
);

CREATE TABLE Location (
    LocationId INT,
    LocationCity NVARCHAR(100),
    LocationState NVARCHAR(100),
    CountryId INT,
    LocationZip NVARCHAR(50)
);

CREATE TABLE Country (
    CountryId INT,
    IsoCountryName NVARCHAR(100)
);
